actions.script:
def _numOk = { v -> v != null && v.toString().trim() != '' && (v.toString().trim() ==~ /\d*\.?\d+/) }
if (!_numOk(quantity)) { ec.message.addError("Quantity must be a number greater than zero."); return }
def _qty = new BigDecimal(quantity)
if (_qty.signum() <= 0) { ec.message.addError("Quantity must be greater than zero."); return }
def _rate = _numOk(unitValue) ? new BigDecimal(unitValue) : BigDecimal.ZERO
def _org = (activeOrg && activeOrg != '_NA_') ? activeOrg : null
def inMap = [
    assetTypeEnumId:'AstTpInventory', classEnumId:'AsClsInventory', statusId:'AstAvailable',
    productId:productId, quantityOnHandTotal:_qty, availableToPromiseTotal:_qty,
    valuationRate:_rate, acquireCost:_rate, expiryDate:expiryDate, receivedDate:ec.user.nowTimestamp
]
if (_org) inMap.ownerPartyId = _org
if (facilityId) inMap.facilityId = facilityId
if (batchNumber) inMap.batchNumber = batchNumber
def _a = ec.service.sync().name("create#mantle.product.asset.Asset").parameters(inMap).call()
ec.service.sync().name("create#mantle.product.asset.AssetDetail").parameters([
    assetId:_a.assetId, productId:productId, effectiveDate:ec.user.nowTimestamp,
    quantityOnHandDiff:_qty, availableToPromiseDiff:_qty, description:'Expiry-tracked stock added']).call()
ec.message.addMessage("Added " + _qty + " units (expiry " + expiryDate + "). It will appear below if it expires within 90 days.")

import java.sql.Timestamp

Calendar cal = Calendar.getInstance()
cal.add(Calendar.DAY_OF_YEAR, 90)
Timestamp thresholdDate = new Timestamp(cal.getTimeInMillis())

// Org isolation (primary guard): a tenant sees only its own expiring stock; a super-admin with
// no active org sees all. Asset is not covered by the active-org entity-filter set, so scope it
// here explicitly — do NOT rely on the Product join below to hide other tenants' stock.
def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
def assetFind = ec.entity.find("mantle.product.asset.Asset")
    .condition("expiryDate", org.moqui.entity.EntityCondition.LESS_THAN_EQUAL_TO, thresholdDate)
    .condition("quantityOnHandTotal", org.moqui.entity.EntityCondition.GREATER_THAN, BigDecimal.ZERO)
if (activeOrg && activeOrg != '_NA_') assetFind.condition("ownerPartyId", activeOrg)
def assetList = assetFind.list()

BigDecimal totalVal = BigDecimal.ZERO
List expList = []
for (def asset : assetList) {
    def product = ec.entity.find("mantle.product.Product").condition("productId", asset.productId).one()
    if (product == null) { continue }  // orphaned/not-visible product — skip, don't value it
    def valRate = asset.valuationRate ?: BigDecimal.ZERO
    def qoh = asset.quantityOnHandTotal ?: BigDecimal.ZERO
    def val = valRate.multiply(qoh)
    totalVal = totalVal.add(val)
    expList.add([
        assetId: asset.assetId,
        productName: product?.productName ?: 'Unknown',
        expiryDate: asset.expiryDate,
        quantity: qoh,
        value: val,
        batchNumber: asset.batchNumber ?: 'N/A'
    ])
}

expiryOut = [totalExpiryValue: totalVal, expiringAssets: expList]
